import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# packet.MotionPredictionHints{EntityRuntimeID: 300, Velocity: mgl32.Vec3{0.5, -1.25, 2}, OnGround: true}
ON_GROUND = bytes.fromhex("ac020000003f0000a0bf0000004001")

# generated by gophertunnel b8bd735:
# packet.MotionPredictionHints{EntityRuntimeID: 0x1234567890, Velocity: mgl32.Vec3{0, 0, 0}, OnGround: false}
WIDE_ID = bytes.fromhex("90f1d9a2a30200000000000000000000000000")

GOLDENS = [
    pytest.param(
        v2225.MotionPredictionHintsPacket(runtime_id=300, motion=v2225.Vec3(x=0.5, y=-1.25, z=2.0), on_ground=True),
        ON_GROUND,
        id="on-ground",
    ),
    pytest.param(v2225.MotionPredictionHintsPacket(runtime_id=0x1234567890), WIDE_ID, id="wide-id"),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225], ids=lambda version: version.__name__.rpartition(".")[2])
def test_motion_prediction_hints_is_packet_157(version):
    assert version.PACKETS[157] is version.MotionPredictionHintsPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_motion_prediction_hints_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_motion_prediction_hints_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
